#include<bits/stdc++.h>
using namespace std;
int main ()
{
    int t , n;
    cin>>t>>n;
    int num_distressed = 0;
    int current = n ; 
    for (int i = 0; i < t; i++)
    {
        char c;
        int x;
        cin>>c>>x;
        if (c == '+')
        {
            current += x;
        }
        else
        {
            if (current >= x)
            {
                current -= x;
            }
            else
            {
                num_distressed++;
            }
        }
        
    }
    cout<<current<<" "<<num_distressed<<endl;
     

}
